mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  float r = length(p.xz);
  float funnel = p.y - (1.0 / (r + 0.4) - 2.0);
  return abs(funnel) - 0.02;
}
